export const ThemeScope = mysqlTable("theme_scopes", {
	id: bigint("id", { mode: "bigint", unsigned: true })
		.autoincrement()
		.primaryKey()
		.notNull(),
	name: varchar("name", { length: 100 }).notNull(),
	type: mysqlEnum("type", ["global", "site", "module", "route"]).notNull(),
	parentId: bigint("parent_id", { mode: "bigint", unsigned: true }),
	siteDomain: varchar("site_domain", { length: 255 }),
	routePath: varchar("route_path", { length: 255 }),
	moduleId: varchar("module_id", { length: 100 }),
	isActive: boolean("is_active").notNull().default(true),
	sortOrder: int("sort_order").notNull().default(0),
	createdAt: datetime("created_at").notNull(),
	updatedAt: datetime("updated_at").notNull(),
});

export const ThemeScopeValue = mysqlTable(
	"theme_scope_values",
	{
		id: bigint("id", { mode: "bigint", unsigned: true })
			.autoincrement()
			.primaryKey()
			.notNull(),
		scopeId: bigint("scope_id", { mode: "bigint", unsigned: true }).notNull(),
		settingKey: varchar("setting_key", { length: 100 }).notNull(),
		settingVal: varchar("setting_val", { length: 255 }).notNull(),
		mode: mysqlEnum("mode", ["light", "dark"]).notNull().default("light"),
		createdAt: datetime("created_at").notNull(),
		updatedAt: datetime("updated_at").notNull(),
	},
	(t) => [
		uniqueIndex("theme_scope_values_unique").on(
			t.scopeId,
			t.settingKey,
			t.mode,
		),
	],
);
